"""A mock implementation of tessaro-feeds for testing."""

import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a certificate DER."""
    return hashlib.sha256(cert_der).hexdigest()


# Pinned certificates: host -> fingerprint mapping
_PINNED = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


class PinStore:
    """A pin store that holds certificate fingerprints per host."""

    def __init__(self, pins: dict = None):
        self._pins = pins or _PINNED.copy()

    @classmethod
    def load(cls) -> "PinStore":
        """Load the default pin store."""
        return cls()

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        """Check if the fingerprint matches the pinned fingerprint for the host."""
        return self._pins.get(host) == cert_fingerprint
